@Composable
fun TrackOrderButton(onTrack: () -> Unit) {
    val launcher = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        onTrack()                                   // tracking works either way; notifications only if granted
    }
    Button(onClick = {
        if (Build.VERSION.SDK_INT >= 33) launcher.launch(Manifest.permission.POST_NOTIFICATIONS) else onTrack()
    }) { Text("Track my order") }
}

fun notifyOrderShipped(context: Context, orderId: String) {
    val open = PendingIntent.getActivity(
        context, orderId.hashCode(),
        Intent(context, MainActivity::class.java).putExtra("orderId", orderId),
        PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
    )
    val n = NotificationCompat.Builder(context, "orders")
        .setSmallIcon(R.drawable.ic_box)
        .setContentTitle("Your order is on its way")
        .setContentText("Arriving tomorrow before 6 pm")
        .setContentIntent(open)
        .setAutoCancel(true)
        .build()
    NotificationManagerCompat.from(context).notify(orderId.hashCode(), n)   // same id updates in place
}

class CameraController(private val context: Context) {
    private val capture = ImageCapture.Builder()
        .setCaptureMode(ImageCapture.CAPTURE_MODE_MINIMIZE_LATENCY)
        .build()

    suspend fun bind(owner: LifecycleOwner, previewView: PreviewView) {
        val provider = ProcessCameraProvider.awaitInstance(context)
        val preview = Preview.Builder().build().also { it.surfaceProvider = previewView.surfaceProvider }
        provider.unbindAll()
        provider.bindToLifecycle(owner, CameraSelector.DEFAULT_BACK_CAMERA, preview, capture)
    }

    fun takePhoto(onSaved: (Uri) -> Unit, onError: (Exception) -> Unit) {
        val file = File(context.filesDir, "photo_${System.currentTimeMillis()}.jpg")
        capture.takePicture(
            ImageCapture.OutputFileOptions.Builder(file).build(),
            ContextCompat.getMainExecutor(context),
            object : ImageCapture.OnImageSavedCallback {
                override fun onImageSaved(r: ImageCapture.OutputFileResults) = onSaved(Uri.fromFile(file))
                override fun onError(e: ImageCaptureException) = onError(e)
            },
        )
    }
}

class ReceiptTextAnalyzer(private val onText: (String) -> Unit) : ImageAnalysis.Analyzer {
    private val recognizer = TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS)
    private var done = false

    @OptIn(ExperimentalGetImage::class)
    override fun analyze(proxy: ImageProxy) {
        val media = proxy.image
        if (done || media == null) { proxy.close(); return }
        recognizer.process(InputImage.fromMediaImage(media, proxy.imageInfo.rotationDegrees))
            .addOnSuccessListener { result ->
                if (result.text.contains("TOTAL", ignoreCase = true)) { done = true; onText(result.text) }
            }
            .addOnCompleteListener { proxy.close() }
    }
}

