@Composable
fun NearbyStoresScreen(vm: StoresViewModel) {
    val launcher = rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { result ->
        val precise = result[Manifest.permission.ACCESS_FINE_LOCATION] == true
        val approx = result[Manifest.permission.ACCESS_COARSE_LOCATION] == true
        if (precise || approx) vm.loadNearby(precise) else vm.showCityPicker()   // still useful without location
    }
    LaunchedEffect(Unit) {
        launcher.launch(arrayOf(Manifest.permission.ACCESS_COARSE_LOCATION, Manifest.permission.ACCESS_FINE_LOCATION))
    }
}

