@SuppressLint("MissingPermission")
fun addStoreGeofence(context: Context, store: Store) {
    val geofence = Geofence.Builder()
        .setRequestId(store.id)
        .setCircularRegion(store.lat, store.lng, 150f)               // metres
        .setExpirationDuration(Geofence.NEVER_EXPIRE)
        .setTransitionTypes(Geofence.GEOFENCE_TRANSITION_ENTER)
        .build()
    val request = GeofencingRequest.Builder()
        .setInitialTrigger(GeofencingRequest.INITIAL_TRIGGER_ENTER)
        .addGeofence(geofence)
        .build()
    val pending = PendingIntent.getBroadcast(context, 0, Intent(context, GeofenceReceiver::class.java),
        PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_MUTABLE)   // Play services fills in the event
    LocationServices.getGeofencingClient(context).addGeofences(request, pending)
}

class GeofenceReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        val event = GeofencingEvent.fromIntent(intent) ?: return
        event.triggeringGeofences?.forEach { showShoppingReminder(context, storeId = it.requestId) }
    }
}

@Composable
fun LessonVideo(url: String, startAt: Long, onPosition: (Long) -> Unit) {
    val context = LocalContext.current
    val player = remember {
        ExoPlayer.Builder(context).build().apply {
            setMediaItem(MediaItem.fromUri(url))
            seekTo(startAt)
            prepare()
            playWhenReady = true
        }
    }
    val lifecycle = LocalLifecycleOwner.current.lifecycle
    DisposableEffect(lifecycle) {
        val observer = LifecycleEventObserver { _, e ->
            if (e == Lifecycle.Event.ON_STOP) { player.pause(); onPosition(player.currentPosition) }
        }
        lifecycle.addObserver(observer)
        onDispose {
            lifecycle.removeObserver(observer)
            onPosition(player.currentPosition)
            player.release()
        }
    }
    AndroidView(factory = { PlayerView(it).apply { this.player = player } },
        modifier = Modifier.fillMaxWidth().aspectRatio(16f / 9f))
}

class TiltViewModel(sensors: SensorManager) : ViewModel() {
    // Pitch and roll in degrees, only while the screen collects.
    val tilt: StateFlow<Pair<Float, Float>> = sensors.events(Sensor.TYPE_ROTATION_VECTOR, SensorManager.SENSOR_DELAY_UI)
        .map { v ->
            val r = FloatArray(9); SensorManager.getRotationMatrixFromVector(r, v)
            val o = FloatArray(3); SensorManager.getOrientation(r, o)
            Math.toDegrees(o[1].toDouble()).toFloat() to Math.toDegrees(o[2].toDouble()).toFloat()
        }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(1_000), 0f to 0f)
}

fun SensorManager.stepsSinceBoot(): Flow<Long> = callbackFlow {
    val sensor = getDefaultSensor(Sensor.TYPE_STEP_COUNTER) ?: run { close(); return@callbackFlow }
    val listener = object : SensorEventListener {
        override fun onSensorChanged(e: SensorEvent) { trySend(e.values[0].toLong()) }
        override fun onAccuracyChanged(s: Sensor, a: Int) = Unit
    }
    registerListener(listener, sensor, SensorManager.SENSOR_DELAY_NORMAL, /* maxReportLatencyUs = */ 60_000_000)
    awaitClose { unregisterListener(listener) }
}

private val HR_SERVICE = UUID.fromString("0000180d-0000-1000-8000-00805f9b34fb")
private val HR_MEASUREMENT = UUID.fromString("00002a37-0000-1000-8000-00805f9b34fb")
private val CCCD = UUID.fromString("00002902-0000-1000-8000-00805f9b34fb")

@SuppressLint("MissingPermission")   // BLUETOOTH_CONNECT checked by the caller
fun BluetoothDevice.heartRate(context: Context): Flow<Int> = callbackFlow {
    val gatt = connectGatt(context, false, object : BluetoothGattCallback() {
        override fun onConnectionStateChange(g: BluetoothGatt, status: Int, state: Int) {
            if (state == BluetoothProfile.STATE_CONNECTED) g.discoverServices()
            else if (state == BluetoothProfile.STATE_DISCONNECTED) close(IOException("Disconnected"))
        }
        override fun onServicesDiscovered(g: BluetoothGatt, status: Int) {
            val ch = g.getService(HR_SERVICE)?.getCharacteristic(HR_MEASUREMENT) ?: return
            g.setCharacteristicNotification(ch, true)
            g.writeDescriptor(ch.getDescriptor(CCCD), BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE)
        }
        override fun onCharacteristicChanged(g: BluetoothGatt, ch: BluetoothGattCharacteristic, value: ByteArray) {
            val is16Bit = value[0].toInt() and 0x01 != 0                 // flags bit 0
            val bpm = if (is16Bit) (value[1].toInt() and 0xFF) or ((value[2].toInt() and 0xFF) shl 8)
                      else value[1].toInt() and 0xFF
            trySend(bpm)
        }
    })
    awaitClose { gatt.close() }
}.retryWhen { e, attempt -> e is IOException && attempt < 5 && run { delay(1_000L shl attempt.toInt()); true } }

