fun publishChatShortcut(context: Context, chat: Chat) {
    val shortcut = ShortcutInfoCompat.Builder(context, "chat_${chat.id}")
        .setShortLabel(chat.name)
        .setIcon(IconCompat.createWithResource(context, R.drawable.ic_chat))
        .setIntent(Intent(Intent.ACTION_VIEW, "https://chat.example/c/${chat.id}".toUri(),
            context, MainActivity::class.java))
        .setLongLived(true)
        .build()
    ShortcutManagerCompat.pushDynamicShortcut(context, shortcut)   // keeps the most recent ones
}
